CREATE OR REPLACE VIEW emp_basic_view AS 
SELECT ENAME, SAL, DEPTNO FROM EMP;

SELECT * FROM emp_basic_view;

CREATE OR REPLACE VIEW emp_dept_name_view AS 
SELECT E.ENAME, D.DNAME 
FROM EMP E JOIN DEPT D ON E.DEPTNO = D.DEPTNO;

SELECT * FROM emp_dept_name_view;

CREATE OR REPLACE VIEW dept10_view AS 
SELECT * FROM EMP WHERE DEPTNO = 10;

SELECT * FROM dept10_view;

CREATE OR REPLACE VIEW annual_sal_view AS 
SELECT ENAME, JOB, SAL * 12 AS ANNUAL_SALARY FROM EMP;

SELECT * FROM annual_sal_view;

CREATE OR REPLACE VIEW dept_loc_view AS 
SELECT DNAME, LOC FROM DEPT;

SELECT * FROM dept_loc_view;

CREATE OR REPLACE VIEW emp_full_dept_view AS 
SELECT E.ENAME, D.DNAME, D.LOC 
FROM EMP E JOIN DEPT D ON E.DEPTNO = D.DEPTNO;

SELECT * FROM emp_full_dept_view;

CREATE OR REPLACE VIEW high_sal_view AS 
SELECT * FROM EMP WHERE SAL > 3000;

SELECT * FROM high_sal_view;

CREATE OR REPLACE VIEW dept_total_sal_view AS 
SELECT DEPTNO, SUM(SAL) AS TOTAL_SALARY 
FROM EMP GROUP BY DEPTNO;

SELECT * FROM dept_total_sal_view;

CREATE OR REPLACE VIEW managers_view AS 
SELECT * FROM EMP WHERE JOB = 'MANAGER';

SELECT * FROM managers_view;

CREATE OR REPLACE VIEW emp_alias_view AS 
SELECT ENAME AS Employee_Name, SAL AS Monthly_Salary FROM EMP;

SELECT * FROM emp_alias_view;
